const menu=document.querySelector('.menu');const nav=document.querySelector('.nav');menu?.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open))});nav?.addEventListener('click',e=>{if(e.target.matches('a')||e.target.closest('.nav-close')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}});document.addEventListener('click',e=>{if(nav&&nav.classList.contains('open')&&!nav.contains(e.target)&&!menu.contains(e.target)){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}});
document.querySelectorAll('.billing button').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.billing button').forEach(b=>b.classList.remove('active'));button.classList.add('active');const period=button.dataset.period;document.querySelectorAll('[data-monthly]').forEach(price=>{price.textContent=price.dataset[period]});document.querySelectorAll('a[href*="/products/"]').forEach(a=>{const u=new URL(a.href,location.origin);if(period==='yearly'){u.searchParams.set('billing','year')}else{u.searchParams.delete('billing')}a.href=u})}));
(()=>{const h=document.querySelector('.site-header'),nav=document.querySelector('.nav');if(!h)return;const HH=h.offsetHeight;let last=scrollY;addEventListener('scroll',()=>{const y=scrollY;if(nav&&nav.classList.contains('open')){last=y;return}if(y<=2){h.classList.remove('scrolled','shown')}else if(y>HH+60){h.classList.add('scrolled');if(y<last-4){h.classList.add('shown')}else if(y>last+4){h.classList.remove('shown')}}last=y},{passive:true})})();
const reviewModal=document.createElement('div');reviewModal.className='review-modal-backdrop';reviewModal.hidden=true;reviewModal.innerHTML=`<section class="review-modal" role="dialog" aria-modal="true" aria-labelledby="review-modal-title" tabindex="-1"><button class="review-close" type="button" aria-label="Close review form">×</button><div class="review-step active" data-review-step="rating"><div class="review-step-head"><h2 id="review-modal-title">How would you rate UNIRAB?</h2><p>We would love it if you would share a bit about your experience.</p></div><div class="rating-picker"><strong>UNIRAB</strong><div class="rating-stars" role="group" aria-label="Choose a rating"><button type="button" data-rating="1" aria-label="1 star">☆</button><button type="button" data-rating="2" aria-label="2 stars">☆</button><button type="button" data-rating="3" aria-label="3 stars">☆</button><button type="button" data-rating="4" aria-label="4 stars">☆</button><button type="button" data-rating="5" aria-label="5 stars">☆</button></div><div class="rating-scale"><span>Poor</span><span>Great</span></div></div></div><form class="review-form" novalidate><div class="review-step" data-review-step="content"><div class="review-step-head compact"><h2 class="review-product-heading">UNIRAB</h2></div><div class="selected-rating" aria-label="Selected rating"></div><label for="review-body">Review content (Required)</label><textarea id="review-body" name="reviewBody" placeholder="Start writing here..." required></textarea><p class="review-terms">We'll only contact you about your review if necessary. By submitting your review, you agree to our <a href="/policies/terms-of-service">terms and conditions</a> and <a href="/policies/privacy-policy">privacy policy</a>.</p><div class="review-actions"><button class="review-back" type="button" data-back="rating">←&nbsp; Back</button><button class="review-next" type="button" data-next="identity">Next</button></div></div><div class="review-step" data-review-step="identity"><div class="review-step-head"><h2>About you</h2><p>Please tell us more about you.</p></div><div class="review-identity"><label for="review-email">Email address (Required)</label><input id="review-email" name="reviewerEmail" type="email" placeholder="Your email address" required><small>We respect your privacy.</small><label for="review-name">Display name (Required)</label><input id="review-name" name="reviewerName" placeholder="Display name" required><label class="anonymous-option"><input name="anonymous" type="checkbox"> <span>Post review as anonymous</span></label></div><div class="review-actions"><button class="review-back" type="button" data-back="content">←&nbsp; Back</button><button class="review-next" type="submit">Next</button></div></div></form><div class="review-step" data-review-step="thanks"><div class="review-step-head"><h2>Thanks for your review!</h2><p>We are processing it and it will appear soon.</p><p>Your review has been saved in this browser for moderation.</p></div><button class="review-done" type="button">Close</button></div></section>`;document.body.append(reviewModal);
let reviewRating=0;let reviewTrigger=null;const modalPanel=reviewModal.querySelector('.review-modal');const reviewForm=reviewModal.querySelector('.review-form');const showReviewStep=step=>{reviewModal.querySelectorAll('.review-step').forEach(el=>el.classList.toggle('active',el.dataset.reviewStep===step));modalPanel.scrollTop=0;const focusTarget=step==='content'?reviewModal.querySelector('#review-body'):step==='identity'?reviewModal.querySelector('#review-email'):modalPanel;setTimeout(()=>focusTarget.focus(),30)};const closeReviewModal=()=>{reviewModal.hidden=true;document.body.classList.remove('modal-open');reviewTrigger?.focus()};const paintRating=()=>{reviewModal.querySelectorAll('[data-rating]').forEach(button=>{const filled=Number(button.dataset.rating)<=reviewRating;button.textContent=filled?'★':'☆';button.setAttribute('aria-pressed',String(Number(button.dataset.rating)===reviewRating))});reviewModal.querySelector('.selected-rating').textContent='★'.repeat(reviewRating)+'☆'.repeat(5-reviewRating)};const openReviewModal=trigger=>{reviewTrigger=trigger;reviewRating=0;reviewForm.reset();paintRating();reviewModal.hidden=false;document.body.classList.add('modal-open');showReviewStep('rating')};
document.addEventListener('click',event=>{const leaveButton=event.target.closest('.write-review-button');if(leaveButton){openReviewModal(leaveButton);return}const closeButton=event.target.closest('.review-close,.review-done');if(closeButton){closeReviewModal();return}const ratingButton=event.target.closest('[data-rating]');if(ratingButton){reviewRating=Number(ratingButton.dataset.rating);paintRating();showReviewStep('content');return}const backButton=event.target.closest('[data-back]');if(backButton){showReviewStep(backButton.dataset.back);return}const nextButton=event.target.closest('[data-next="identity"]');if(nextButton){const reviewBody=reviewModal.querySelector('#review-body');if(reviewBody.reportValidity())showReviewStep('identity');return}if(event.target===reviewModal)closeReviewModal()});
reviewForm.addEventListener('submit',event=>{event.preventDefault();if(!reviewForm.reportValidity()||!reviewRating)return;const values=Object.fromEntries(new FormData(reviewForm));const saved=JSON.parse(localStorage.getItem('unirab-reviews')||'[]');saved.unshift({plan:'homepage',rating:reviewRating,reviewBody:values.reviewBody,reviewerEmail:values.reviewerEmail,reviewerName:values.anonymous?'Anonymous':values.reviewerName,anonymous:Boolean(values.anonymous),createdAt:new Date().toISOString()});localStorage.setItem('unirab-reviews',JSON.stringify(saved.slice(0,25)));showReviewStep('thanks')});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!reviewModal.hidden)closeReviewModal()});

document.querySelector('.review-form')?.addEventListener('submit',e=>{try{const fd=new FormData(e.target);fetch('/api/reviews',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({rating:reviewRating,reviewBody:fd.get('reviewBody'),reviewerName:fd.get('reviewerName'),reviewerEmail:fd.get('reviewerEmail'),anonymous:fd.get('anonymous'),plan:document.body.dataset.plan||'homepage'})}).catch(()=>null)}catch(err){}});
fetch('/api/reviews').then(r=>r.json()).then(d=>{const grid=document.querySelector('.story-grid');if(!grid||!d.reviews||!d.reviews.length)return;const esc=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');d.reviews.forEach(r=>{const art=document.createElement('article');const stars='★'.repeat(Math.min(5,Math.max(1,r.rating||5)))+'☆'.repeat(5-Math.min(5,Math.max(1,r.rating||5)));const dt=new Date(r.ts).toLocaleDateString('en-US',{month:'short',year:'numeric'});art.innerHTML=`<span>${stars}</span><blockquote>“${esc(r.body)}”</blockquote><b>${esc(r.name)}</b><small>UNIRAB customer · ${dt}</small>`;grid.appendChild(art)})}).catch(()=>{});
